const processTeamPhases=[
['Business owner + people doing the work','Show the current workflow, real examples, exceptions, and desired outcome.','Map the workflow, establish a baseline, and recommend the first use case.','A focused scope and a named team with agreed responsibilities.'],
['Business owner + representative users','Walk through the prototype and confirm the screens, review points, and priorities.','Design the experience and make AI responsibilities and human approvals explicit.','An agreed prototype and acceptance criteria before the full build.'],
['IT / security + data or system owners','Confirm access, permissions, source quality, and the approved environment.','Define integrations, data flow, access controls, and implementation dependencies.','An agreed connection plan and a clear list of access requirements.'],
['Workflow owner + a small user group','Review working increments and flag gaps using realistic examples.','Build the application, demonstrate progress, and incorporate feedback.','A working application refined through short, focused reviews.'],
['Representative users + subject matter experts','Validate real scenarios and specialist answers; confirm the workflow is useful.','Run end-to-end checks, evaluate AI outputs, and fix issues before release.','Acceptance evidence, known limitations, and an agreed launch decision.'],
['Business owner + pilot users + operational owner','Try the application in daily work, share feedback, and review the results.','Support onboarding, monitor the agreed measures, and prioritize improvements.','A supported pilot, clear ownership, and evidence for the next step.']
];
function processTeamPanel(){const a=processTeamPhases[processStage];return `<section class="process-team-phase"><span class="process-eyebrow">HOW WE WORK TOGETHER IN THIS PHASE</span><div><article><small>YOUR TEAM</small><h4>${a[0]}</h4><p>${a[1]}</p></article><article><small>NINE-67</small><h4>We lead the delivery work</h4><p>${a[2]}</p></article></div><footer><b>What we agree together</b><span>${a[3]}</span></footer></section>`}
function processWorkingTogether(){return `<section id="workingTogether" class="process-section"><div class="process-section-heading"><div><span class="process-eyebrow">YOUR PEOPLE + OUR BUILD TEAM</span><h2>A small working team.<br>A clear role for everyone.</h2></div><p>We work alongside the people who own and perform the workflow. You provide the business context and decisions; Nine-67 leads the design, engineering, testing, and delivery.</p></div><div class="process-role-grid">${[
['01','Business owner','Sets the direction','Agrees on the business outcome, priorities, scope, and acceptance.','Discovery · key decisions · outcome reviews'],
['02','People doing the work','Make it practical','Show the current process, share examples and exceptions, and test the working application.','Workflow walkthrough · prototype reviews · pilot'],
['03','IT & system owners','Enable the connections','Confirm the approved environment, access, permissions, data sources, and security requirements.','Access planning · integration reviews · launch'],
['04','Subject matter experts','Validate specialist work','Review domain-specific answers, rules, and edge cases when the application needs expert judgment.','Targeted reviews · AI evaluation · acceptance']
].map(([n,h,sub,b,when])=>`<article><span>${n}</span><h3>${h}</h3><b>${sub}</b><p>${b}</p><footer><small>WHEN WE INVOLVE THEM</small>${when}</footer></article>`).join('')}</div><div class="process-resource-plan"><div><span class="process-eyebrow">HOW WE DETERMINE THE COMMITMENT</span><h3>We scope the work before we ask for your time.</h3><p>The number of workflows, systems, data sources, user roles, and approval requirements determines who needs to participate and when.</p></div><ol><li><b>Map the workflow</b><span>Identify tasks, handoffs, exceptions, and the people involved.</span></li><li><b>Identify dependencies</b><span>Confirm data access, integrations, expertise, and decision makers.</span></li><li><b>Agree the resource plan</b><span>Name the participants, their tasks, estimated time, and review milestones.</span></li></ol><footer><b>Your commitment is visible before the build.</b><span>Expect more involvement during discovery and user testing, with short reviews during development. We agree the actual hours and cadence with you for the selected scope.</span></footer></div><div class="process-cadence"><span>THE WORKING RHYTHM</span><b>Walk through the work</b><i>→</i><b>Review something tangible</b><i>→</i><b>Test with real examples</b><i>→</i><b>Launch with a small group</b></div></section>`}
let processStage=0;
const nine67Process=[
['Discover the workflow','Start with the work, not the technology.','We work with the people doing the task to understand the handoffs, decisions, source information, and points of friction. Together we define the problem worth solving.',[['Workflow map','Who does what, where information comes from, and what happens next.'],['Baseline & desired outcome','A practical measure of the current effort and what improvement would mean.'],['People & constraints','Users, process owners, existing systems, and access requirements.']],'What does your team repeat every week that still takes too much manual effort?'],
['Design the experience','Make the new way of working tangible.','We shape the screens and interactions around real tasks. An early prototype gives the team something concrete to react to before the full application is built.',[['Interactive prototype','The main screens and critical user journeys to explore together.'],['AI responsibilities','Which steps AI assists, which inputs it needs, and where people review.'],['Agreed scope','The first workflow, exclusions, priorities, and acceptance criteria.']],'Can a user understand what to do next without needing the builder beside them?'],
['Connect the right information','Bring the context into the workflow.','We identify approved source systems and plan the connections the application needs. Access, data quality, and source ownership shape the implementation.',[['Source inventory','The documents, records, reports, and systems the workflow depends on.'],['Access approach','Identity, roles, and permissions appropriate to each participant.'],['Integration plan','How data enters the application, stays current, and can be traced back.']],'Which information can the application access—and who is responsible for keeping it accurate?'],
['Build the application','Turn the workflow into a working product.','We build the interface, application logic, data model, and AI-assisted steps as one experience. The team reviews working increments and helps refine the details.',[['Working application','A usable interface connected to the agreed workflow and data.'],['AI behavior','Instructions, context, output formats, and review points specific to the task.'],['Operational controls','Logging, error handling, usage controls, and recovery paths as scoped.']],'Does the application handle the actual task, including the exceptions that happen in real work?'],
['Test the complete journey','Verify the whole experience.','We test complete user journeys, calculations, permissions, and AI outputs against agreed examples. Findings drive corrections before a release is accepted.',[['End-to-end checks','From initial input through the final reviewed output.'],['AI evaluation','Representative examples, unsupported claims, missing context, and output quality.'],['Release review','Known limitations, acceptance evidence, and operational readiness.']],'Can the intended user complete the workflow reliably with representative inputs?'],
['Launch, learn & improve','Make the application useful in practice.','We introduce the application to its users, review feedback, and compare outcomes with the baseline. Ongoing refinement focuses on what improves the work.',[['User onboarding','Practical guidance for the people who will use and own the workflow.'],['Outcome review','Adoption, time spent, quality, and other agreed measures.'],['Improvement backlog','Prioritized adjustments based on observed use and business value.']],'Are people using it, and is the workflow measurably better?']
];
const nine67Toolkit=[
['AI & reasoning','Claude API','Context-aware drafting, document analysis, structured outputs, and task-specific reasoning.','spark'],
['AI & reasoning','OpenAI API','Conversational interfaces, extraction, analysis, and other model capabilities selected for the workflow.','spark'],
['Collaboration','Microsoft Teams','Bring project conversation, notifications, and team review into the way people already collaborate.','collab'],
['Collaboration','SharePoint','Connect approved documents, reference material, project files, and source context with appropriate permissions.','file'],
['Cloud & data','Azure','Cloud services, identity integration, processing, and enterprise connections chosen for the client environment.','settings'],
['Cloud & data','Supabase','Postgres data, application records, and supporting backend services where they fit the implementation.','budget'],
['Cloud & data','Vercel','Application deployment and web delivery where appropriate to the hosting requirements.','grid'],
['Development','Claude Code & Codex','AI-assisted engineering tools used by our builders to develop, inspect, and iterate on application code.','projects'],
['Development','TypeScript, React & Python','Application interfaces, backend logic, integrations, and data processing using the tools appropriate to the project.','settings']
];
function processSelect(i){processStage=i;render();document.getElementById('processDetail').scrollIntoView({behavior:'smooth',block:'nearest'})}
function processJump(id){document.getElementById(id).scrollIntoView({behavior:'smooth',block:'start'})}
studioHome=function(){const p=nine67Process[processStage];return `<div class="process-page"><section class="process-hero"><div class="process-hero-copy"><span class="process-eyebrow">NINE-67 / OUR PROCESS & TECHNOLOGY</span><h1>The AI Operating Layer<br>Built Around Your Business.</h1><p>Explore how Nine-67 designs, builds, and embeds AI applications into the workflows that drive revenue, efficiency, and clearer decisions.</p><div class="process-actions"><button class="client-primary" onclick="processJump('ourProcess')">See our process ${icon('arrow')}</button><button class="client-secondary" onclick="processJump('workingTogether')">How we work with your team</button></div></div><div class="process-hero-aside"><span>WHAT WE BRING TOGETHER</span>${[['Your workflow','The real task and the people responsible for it.'],['Your information','Approved data and the systems your team uses.'],['Purpose-built AI','Assistance designed for a specific business outcome.']].map(([h,b],i)=>`<div><small>0${i+1}</small><section><h3>${h}</h3><p>${b}</p></section></div>`).join('')}<p class="process-aside-note">Explore the ${toolsList.length} applications on the homepage to see these ideas in action.</p></div></section>${processWorkingTogether()}<section id="ourProcess" class="process-section"><div class="process-section-heading"><div><span class="process-eyebrow">HOW WE WORK</span><h2>A clear path from idea to adoption.</h2></div><p>Each project is shaped around its users, scope, and requirements. Select a phase to see the work and the outputs.</p></div><div class="process-workbench"><nav aria-label="Delivery process" class="process-stages">${nine67Process.map((s,i)=>`<button class="${i===processStage?'active':''}" aria-pressed="${i===processStage}" onclick="processSelect(${i})"><span>${String(i+1).padStart(2,'0')}</span><b>${s[0]}</b>${icon('arrow')}</button>`).join('')}</nav><div id="processDetail" class="process-detail"><span class="process-eyebrow">PHASE ${String(processStage+1).padStart(2,'0')} / ${p[0]}</span><h3>${p[1]}</h3><p>${p[2]}</p><div class="process-deliverables">${p[3].map(([h,b])=>`<section><h4>${icon('check')}${h}</h4><p>${b}</p></section>`).join('')}</div>${processTeamPanel()}<div class="process-question"><span>THE QUESTION WE NEED TO ANSWER</span><p>${p[4]}</p></div><div class="process-detail-controls">${processStage>0?`<button onclick="processSelect(${processStage-1})">Previous phase</button>`:'<span></span>'}${processStage<5?`<button onclick="processSelect(${processStage+1})">Next phase ${icon('arrow')}</button>`:`<button onclick="processJump('ourTechnology')">Explore the technology ${icon('arrow')}</button>`}</div></div></div></section><section id="ourTechnology" class="process-section"><div class="process-section-heading"><div><span class="process-eyebrow">THE TOOLS BEHIND THE WORK</span><h2>Connected technology.<br>One useful application.</h2></div><p>We select the combination that fits the workflow, client environment, and operating requirements. Every project does not need every tool.</p></div><div class="process-toolkit">${['AI & reasoning','Collaboration','Cloud & data','Development'].map((group,i)=>`<section class="process-tech-group"><div class="process-tech-label"><span>0${i+1}</span><h3>${group==='Collaboration'?'<img class="technology-logo microsoft-group-logo" src="logos/microsoft.svg" alt="Microsoft" width="20" height="20">':''}${group}</h3></div>${nine67Toolkit.filter(t=>t[0]===group).map(t=>`<article><div><h4>${technologyBrand(t[1])}</h4><p>${t[2]}</p></div></article>`).join('')}</section>`).join('')}</div></section><section class="process-principles"><div><span class="process-eyebrow">DESIGNED FOR THE WAY YOU OPERATE</span><h2>The details matter<br>as much as the demo.</h2></div><div>${[['People stay in control','Review and approval points are designed around the consequences of each action.'],['Context stays visible','Sources, assumptions, and limitations should be available when a user makes a decision.'],['Access fits the role','Internal users, clients, and contractors may need different views and permissions.'],['Value is measured in the work','Agree on the baseline and useful outcome, then review what changes after adoption.']].map(([h,b])=>`<section><h3>${h}</h3><p>${b}</p></section>`).join('')}</div></section><section class="process-close"><div><span class="process-eyebrow">EXPLORE THE APPLICATIONS</span><h2>See the process<br>in practice.</h2><p>Open any application on the homepage to walk through its workflow, explore the sample data, and try the AI simulations.</p></div><div class="process-demo-links"><span>SEE THE APPROACH IN ACTION</span>${[[0,'A proposal that starts with a conversation'],[7,'A shared workspace for project delivery'],[13,'An explainable view of client relationships']].map(([i,h])=>`<button onclick="nav(${i})"><div><small>${toolsList[i][0]}</small><b>${h}</b></div>${icon('arrow')}</button>`).join('')}</div></section><p class="process-disclosure">The collection contains representative interactive demos using sample data and simulated AI. Implementation scope, integrations, hosting, and controls are agreed for each project.</p></div>`};
render();
